<?php
declare(strict_types=1);
function reviews_private_dir(): string { return dirname(__DIR__, 2) . '/private'; }
function reviews_config(): array { $f=reviews_private_dir().'/admin.php'; if(!is_file($f)) return []; $v=require $f; return is_array($v)?$v:[]; }
function reviews_data_file(): string { return reviews_private_dir().'/reviews.json'; }
function reviews_read_all(): array { $f=reviews_data_file(); if(!is_file($f)) return []; $v=json_decode((string)file_get_contents($f),true); return is_array($v)?$v:[]; }
function reviews_write_all(array $items): bool { $d=reviews_private_dir(); if(!is_dir($d)&&!mkdir($d,0750,true)&&!is_dir($d)) return false; $j=json_encode(array_values($items),JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT|JSON_INVALID_UTF8_SUBSTITUTE); if($j===false)return false; $t=reviews_data_file().'.tmp'; if(file_put_contents($t,$j,LOCK_EX)===false)return false; return rename($t,reviews_data_file()); }
function reviews_start_session(): void { if(session_status()===PHP_SESSION_ACTIVE)return; session_name('artcity_admin'); session_set_cookie_params(['httponly'=>true,'secure'=>!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off','samesite'=>'Strict','path'=>'/']); session_start(); }
function reviews_json(array $d,int $s=200): never { http_response_code($s); header('Content-Type: application/json; charset=utf-8'); header('Cache-Control: no-store'); echo json_encode($d,JSON_UNESCAPED_UNICODE|JSON_INVALID_UTF8_SUBSTITUTE); exit; }
function reviews_require_admin(): void { reviews_start_session(); if(empty($_SESSION['admin_ok']))reviews_json(['ok'=>false,'error'=>'Требуется вход'],401); }
function reviews_check_csrf(): void { $v=$_SERVER['HTTP_X_CSRF_TOKEN']??($_POST['csrf']??''); if(!is_string($v)||empty($_SESSION['csrf'])||!hash_equals($_SESSION['csrf'],$v))reviews_json(['ok'=>false,'error'=>'Сессия формы устарела. Обновите страницу.'],403); }
function reviews_upload_photos(array $f): array { $d=dirname(__DIR__).'/uploads/reviews'; if(!is_dir($d)&&!mkdir($d,0755,true)&&!is_dir($d))throw new RuntimeException('Не удалось создать папку фотографий.'); $allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp']; $out=[]; $n=is_array($f['name']??null)?count($f['name']):0; if($n>10)throw new RuntimeException('За один раз можно загрузить не более 10 фотографий.'); $fi=new finfo(FILEINFO_MIME_TYPE); for($i=0;$i<$n;$i++){if(($f['error'][$i]??4)===4)continue; if(($f['error'][$i]??0)!==0)throw new RuntimeException('Ошибка загрузки фотографии.'); if(($f['size'][$i]??0)>8388608)throw new RuntimeException('Размер одной фотографии не должен превышать 8 МБ.'); $tmp=$f['tmp_name'][$i]??''; $mime=is_uploaded_file($tmp)?$fi->file($tmp):''; if(!isset($allowed[$mime])||@getimagesize($tmp)===false)throw new RuntimeException('Допускаются только изображения JPG, PNG и WebP.'); $name=bin2hex(random_bytes(16)).'.'.$allowed[$mime]; if(!move_uploaded_file($tmp,$d.'/'.$name))throw new RuntimeException('Не удалось сохранить фотографию.'); $out[]='/uploads/reviews/'.$name;} return $out; }
function reviews_delete_image(string $url): void { if(!preg_match('~^/uploads/reviews/[a-f0-9]{32}\.(jpg|png|webp)$~',$url))return; $p=dirname(__DIR__).$url; if(is_file($p))@unlink($p); }
